package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var t int64 = 1
	for ; t > 0; t-- {
		var n, m, k int64
		fmt.Fscan(reader, &n, &m, &k)
		a := make([]int64, n)
		for i := int64(0); i < n; i++ {
			fmt.Fscan(reader, &a[i])
		}
		sort.Slice(a, func(i, j int) bool { return a[i] < a[j] })
		if m <= k {
			fmt.Fprint(writer, 0)
		} else {
			sum, i, devices, soc := int64(0), n, m, k
			for sum < m && devices > soc && i >= 1 {
				i--
				sum += a[i]
				devices -= a[i]
				soc--
			}
			if devices <= soc {
				fmt.Fprint(writer, n-i)
			} else {
				i2, used, ss, j := n, int64(0), int64(0), int64(0)
				for i2 >= 1 && ss < m {
					i2--
					if used >= k*j && j >= 1 {
						ss--
					}
					ss += a[i2]
					used++
					if used%k == 0 && used != 0 {
						j++
					}
				}
				if ss >= m {
					fmt.Fprint(writer, used)
				} else {
					fmt.Fprint(writer, -1)
				}
			}
		}
	}
}
